  static const double body = 16;
  static const double title = 20;
  static const double heading = 28;
  static const double display = 40;
  static const double hero = 64;
}

/// Corner radii: only two exist.
abstract final class DesignRadius {
  static const double control = 4;
  static const double card = 8;
}

/// Control and row heights. Touch targets are never below 44; the POS uses controlLg (48).
abstract final class DesignSizes {
  static const double controlSm = 32;
  static const double controlMd = 40;
  static const double controlLg = 48;
  static const double rowCompact = 32;
  static const double rowComfortable = 44;
}

/// Keyboard/accessibility focus outline.
abstract final class DesignFocus {
  static const double width = 2;
  static const double offset = 2;
}

/// Durations and curves for animation. Motion explains a change and never blocks work.
abstract final class DesignMotion {
